annotations.text:
@Tool(name = "askUser", description = "关键意图或必要信息不明确且无法从已有上下文确定时，向用户提一个明确问题。"
            + "可给最多4个选项及简短影响说明，用户也可自由输入。调用后引擎暂停任务等待回答；不要自行替用户选择。"
            + "不用于授权删除或外部写操作，那些仍走人工确认。已回答的问题不要重复问。")

@Tool(name = "failPlanStep",
            description = "把计划中的某一步标记为失败。失败后可以重试该步（startPlanStep），"
                    + "或用 revisePlan 换一条路线。不要反复用同样的参数重试。")

@Tool(name = "revisePlan",
            description = "放弃当前计划并建立新计划（换路线）。原计划保留为已放弃状态，便于回溯。"
                    + "当某步失败且重试也无意义、或用户改了需求时调用。")

@Tool(name = "findTasks",
            description = "按关键词或状态查询任务列表。用户问「我有哪些待办」「找一下周报相关的任务」时调用。"
                    + "返回结果包含任务 id，后续需要按 id 操作时必须先调用本工具获取 id。")

@Tool(name = "updateTaskDetails",
            description = "修改任务的标题或描述。这两个字段可逆、影响局部，因此无需用户确认。"
                    + "修改截止时间请用 scheduleTask，修改优先级请用 setTaskPriority。")

@Tool(name = "scheduleTask",
            description = "申请修改任务的截止时间。截止时间属于关键字段，调用后不会立即生效，"
                    + "而是生成待确认事项，需用户在界面上确认。省略 dueAt 表示清除截止时间。")

@Tool(name = "setTaskPriority",
            description = "申请修改任务的优先级。优先级属于关键字段，调用后不会立即生效，"
                    + "而是生成待确认事项，需用户在界面上确认。")

@Tool(name = "findDueReminders",
            description = "查看当前已经到点、尚未处理的提醒（来自日程或任务）。"
                    + "用户问「有什么要提醒我的」时调用。")

@Query(value = "SELECT DISTINCT conversation_id FROM chat_message "
            + "WHERE lower(content) LIKE lower(?1) ESCAPE '\\'",
            nativeQuery = true)

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
        "spring.ai.model.chat=none",
        "app.ai.memory.max-messages=6",
        // 本类的断言都基于「桩模型最后一次收到的指令」，而轮末摘要刷新会**再调一次**桩模型。
        // 把触发阈值调到够不着，保证异步摘要永不在这些用例里发生（注入路径另有用例覆盖）。
        "app.context.summary.min-messages=100000"
})

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
        "spring.ai.model.chat=none",
        // 1500ms：要同时满足两件相反的事 ——
        //   ① 慢尾 3 秒必须超时（1500 < 3000，留了一倍余量）
        //   ② 互斥用例在「模型已进入」之后发第二条请求，此时第一条流必须还活着。
        // 原先是 400ms，而互斥用例 sleep(400) 等锁，两者零余量对齐，实测只剩 68ms，
        // 换线程模型就翻车。放宽到 1500ms 后，从模型进入到超时还有约 1.4 秒可用，
        // 发一个本地请求绰绰有余。
        "app.chat.stream-timeout=1500ms",
        // 关掉异步摘要，避免它再调一次桩模型干扰断言
        "app.context.summary.min-messages=100000"
})

@SpringBootTest(properties = {
        "spring.ai.model.chat=none",
        "spring.ai.model.embedding=none",
        // 关掉限流：令牌桶是进程级单例，跨测试上下文共享计数（见 src/test/resources/application.properties）
        "app.rate-limit.enabled=false"
})

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
        "spring.ai.model.chat=none",
        "spring.ai.model.embedding=none",
        "app.calendar.scan-enabled=false",
        // 测试夹具刻意极短（几行文本 / 极小 PDF），只为验证其他行为；
        // 入库长度下限由 KnowledgeMinLengthIntegrationTest 专门覆盖
        "app.knowledge.min-chunk-size-chars=20"
})

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
        "spring.ai.model.chat=none",
        "spring.ai.model.embedding=none",
        "app.calendar.scan-enabled=false",
        // 测试夹具刻意极短（几行文本 / 极小 PDF），只为验证其他行为；
        // 入库长度下限由 KnowledgeMinLengthIntegrationTest 专门覆盖
        "app.knowledge.min-chunk-size-chars=20"
})

@SpringBootTest(properties = {
        // 关掉自动装配的模型，否则会与下面的桩模型同时存在，
        // PgVectorStore 拿不到唯一的 EmbeddingModel（NoUniqueBeanDefinition）
        "spring.ai.model.chat=none",
        "spring.ai.model.embedding=none"
})

@SpringBootTest(properties = {
        "spring.ai.model.chat=none",
        "spring.ai.model.embedding=none",
        // 本用例要验证的是**写入那一刻**的维度报错，夹具刻意极短；
        // 若不放宽入库长度下限，28 字符的夹具会先被长度校验拦下（错误码不同），
        // 根本走不到向量写入。长度下限由 KnowledgeMinLengthIntegrationTest 专门覆盖。
        "app.knowledge.min-chunk-size-chars=20"
})

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
        "spring.ai.model.chat=none",
        "spring.ai.model.embedding=none",
        "app.calendar.scan-enabled=false",
        // 阈值置 0：词袋相似度没有校准意义，这里不验证阈值过滤
        "app.knowledge.similarity-threshold=0.0",
        "app.knowledge.min-chunk-size-chars=20"
})

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
        "spring.ai.model.chat=none",
        "spring.ai.model.embedding=none",
        // 词袋相似度是「词面重叠」的线性映射，具体数值没有校准意义。
        // 排序断言本身不需要阈值，故置 0 只验证排序与召回，不验证阈值过滤。
        "app.knowledge.similarity-threshold=0.0",
        // 下面的两个主题文档是刻意写短的（主题 A/B 零词面重叠，才能干净地测检索区分度）。
        // 生产默认的 350 字符下限会把它们拒收，而那不是本类要测的东西 ——
        // 入库长度下限有专属的 KnowledgeMinLengthIntegrationTest。
        "app.knowledge.min-chunk-size-chars=40"
})

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
        "spring.ai.model.chat=none",
        "spring.ai.model.embedding=none",
        // 词袋相似度是词面重叠的线性映射，阈值置 0 只验证排序与召回
        "app.knowledge.similarity-threshold=0.0",
        // 测试夹具刻意极短（几行文本 / 极小 PDF），只为验证其他行为；
        // 入库长度下限由 KnowledgeMinLengthIntegrationTest 专门覆盖
        "app.knowledge.min-chunk-size-chars=20"
})

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
        "mcp.enabled=true",
        // 关掉真实模型：桩模型是唯一的 ChatModel，否则会与 ollamaChatModel 撞成两个候选
        "spring.ai.model.chat=none"
})

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
        properties = {
                "mcp.enabled=true",
                "mcp.servers.broken.command=/nonexistent/mcp-server",
                // 关掉全部真实模型：模拟「没装 Ollama、也没配 API Key」
                "spring.ai.model.chat=none",
        })

